<?php ob_start(); ?>
<h1>File changes</h1><p class="muted">Recent snapshot changes grouped by scan/site. Differential scans track new, modified, deleted, skipped unchanged, and suspicious changed files.</p>
<?php if(!empty($lastRuns)): ?><div class="card"><h2>Differential scan summary</h2><table><tr><th>Scan</th><th>Mode</th><th>Previous</th><th>Seen</th><th>New</th><th>Modified</th><th>Deleted</th><th>Changed</th><th>Analyzed</th><th>Unchanged skipped</th></tr><?php foreach($lastRuns as $r): ?><tr><td>#<?= e($r['id']) ?></td><td><?= e($r['scan_mode'] ?? 'full') ?></td><td><?= e($r['previous_scan_id'] ?? '') ?></td><td><?= e($r['files_seen_total'] ?? 0) ?></td><td><?= e($r['files_new'] ?? 0) ?></td><td><?= e($r['files_modified'] ?? 0) ?></td><td><?= e($r['files_deleted'] ?? 0) ?></td><td><?= e($r['files_changed_total'] ?? 0) ?></td><td><?= e($r['files_analyzed'] ?? 0) ?></td><td><?= e($r['files_skipped_unchanged'] ?? 0) ?></td></tr><?php endforeach ?></table></div><?php endif ?>
<form><input class="input" name="path" placeholder="Path contains / keyword" value="<?= e($_GET['path']??'') ?>"> <select class="input" name="kind"><option value="">All changes</option><?php foreach(['new'=>'New files','modified'=>'Modified/recently changed','deleted'=>'Deleted files','skipped'=>'Unchanged skipped','suspicious'=>'Suspicious changed files','webroot'=>'Web root files','htaccess'=>'.htaccess','google'=>'google*.html','php'=>'.php','html'=>'.html','seo'=>'SEO keywords'] as $k=>$label): ?><option value="<?= e($k) ?>" <?= ($_GET['kind']??'')===$k?'selected':'' ?>><?= e($label) ?></option><?php endforeach ?></select> <button class="btn">Filter</button></form>
<table><tr><th>Site</th><th>Change</th><th>Path</th><th>Category</th><th>Size</th><th>MTime</th><th>First scan</th><th>Last seen scan</th><th>Last changed scan</th></tr><?php foreach($changes as $c): $kind=($c['is_missing']??0)?'deleted':(($c['first_seen_scan_id']??null)==($c['last_seen_scan_id']??null)?'new':(((int)($c['last_changed_scan_id']??0)==(int)($c['last_seen_scan_id']??-1))?'modified':'unchanged')); ?><tr><td><?= e($c['site_name'] ?? '') ?></td><td><span class="badge <?= $kind==='deleted'?'critical':($kind==='new'?'high':($kind==='modified'?'medium':'low')) ?>"><?= e($kind) ?></span></td><td class="uri-cell"><code><?= e($c['relative_path'] ?: $c['path']) ?></code></td><td><?= e($c['file_category'] ?? '') ?></td><td><?= e($c['size']) ?></td><td><?= e($c['mtime']) ?></td><td><?= e($c['first_seen_scan_id'] ?? '') ?></td><td><?= e($c['last_seen_scan_id'] ?? '') ?></td><td><?= e($c['last_changed_scan_id'] ?? '') ?></td></tr><?php endforeach ?></table><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
